joblib.dump(platt, f"{ARTIFACT_DIR}/platt_calibrator.joblib")

def make_defaults(frame, feats):
    out = {}
    for c in feats:
        s = frame[c]
        if pd.api.types.is_numeric_dtype(s):
            out[c] = None if pd.isna(s.median()) else float(s.median())
        else:
            m = s.mode(dropna=True); out[c] = None if len(m) == 0 else str(m.iloc[0])
    return out

metadata = {"feature_cols": feature_cols, "numeric_features": numeric_features,
            "categorical_features": categorical_features, "defaults": make_defaults(train_df, feature_cols),
            "LGD_measured_net": LGD, "FUNDING_COST_assumed": FUNDING_COST, "OPERATING_MARGIN_assumed": OPERATING_MARGIN}
with open(f"{ARTIFACT_DIR}/metadata.json", "w") as fh:
    json.dump(metadata, fh, indent=2)
print("Saved to", ARTIFACT_DIR)

LAUNCH_APP = False   # set True to start the Gradio demo
if LAUNCH_APP:
    import gradio as gr
    UI = [c for c in ["loan_amnt", "annual_inc", "dti", "fico_avg", "revol_util", "inq_last_6mths",
                      "delinq_2yrs", "open_acc", "term", "home_ownership", "purpose"] if c in feature_cols]

    def score_application(*vals):
        row = metadata["defaults"].copy()
        row.update(dict(zip(UI, vals)))
        raw = best_xgb.predict_proba(pd.DataFrame([row], columns=feature_cols))[:, 1]
        p = float(platt.predict_proba(logit_t(raw))[:, 1][0])
        return {"default_probability": round(p, 4),
                "expected_loss_rate": round(p * LGD, 4),
                "simulated_suggested_rate": round(float(suggested_rate(p)), 4)}

    comps = []
    for c in UI:
        if c in categorical_features:
            ch = sorted(train_df[c].dropna().astype(str).unique())[:50]
            comps.append(gr.Dropdown(choices=ch, value=str(metadata["defaults"][c]), label=c))
        else:
            comps.append(gr.Number(value=metadata["defaults"][c], label=c))
    gr.Interface(fn=score_application, inputs=comps, outputs=gr.JSON(label="Risk & pricing"),
                 title="Risk-based pricing simulator (educational)").launch(share=False)
